#define NLMSG_TAIL(nmsg) \
    ((struct nlattr *)(((char *)(nmsg)) + NLMSG_ALIGN((nmsg)->nlmsg_len)))

static void nla_put_raw(struct nlmsghdr *nlh, int type, int len, const void *data)
{
    struct nlattr *nla = NLMSG_TAIL(nlh);
    int nla_len = NLA_HDRLEN + len;
    nla->nla_type = type;
    nla->nla_len  = (uint16_t)nla_len;
    memcpy((char *)nla + NLA_HDRLEN, data, len);
    nlh->nlmsg_len = NLMSG_ALIGN(nlh->nlmsg_len) + NLA_ALIGN(nla_len);
}

static struct nlattr *nla_nest_start(struct nlmsghdr *nlh, int type)
{
    struct nlattr *nla = NLMSG_TAIL(nlh);
    nla->nla_type = type;
    nla->nla_len  = NLA_HDRLEN;
    nlh->nlmsg_len = NLMSG_ALIGN(nlh->nlmsg_len) + NLA_HDRLEN;
    return nla;
}

static void nla_nest_end(struct nlmsghdr *nlh, struct nlattr *nla)
{
    nla->nla_len = (uint16_t)((char *)NLMSG_TAIL(nlh) - (char *)nla);
}

static void nla_put_u32(struct nlmsghdr *nlh, int type, uint32_t val)
{
