    struct iovec iov;
    struct msghdr msg;

    memset(&sa, 0, sizeof(sa));
    sa.nl_family = AF_NETLINK;

    iov.iov_base = nlh;
    iov.iov_len  = nlh->nlmsg_len;

    memset(&msg, 0, sizeof(msg));
    msg.msg_name    = &sa;
    msg.msg_namelen = sizeof(sa);
    msg.msg_iov     = &iov;
    msg.msg_iovlen  = 1;

    if (sendmsg(fd, &msg, 0) < 0) {
        perror("sendmsg");
        return -1;
    }
    return 0;
}

static int recv_ack(int fd, const char *label)
